"use client"

import NextImage, { type ImageProps as NextImageProps } from "next/image"
import { type CSSProperties, type Ref, useState } from "react"
import { cn } from "@/lib/utils"

export type ImageProps = Omit<NextImageProps, "placeholder"> & {
  /** Classes on the pixels, e.g. object-contain or object-top. className styles the frame. */
  imageClassName?: string
  ref?: Ref<HTMLImageElement>
}

/** Next.js optimization on any Next host. Supply dimensions (or a sized parent
 * with fill); remote/public assets can supply a prepared blurDataURL. Static
 * imports provide dimensions and a blur automatically. No fetch for a placeholder. */
export function Image({ src, ...props }: ImageProps) {
  const data =
    typeof src === "object" ? ("default" in src ? src.default : src) : null
  // A new source owns a new load lifecycle, including when the old request finishes late.
  return <ImageResource key={data?.src ?? String(src)} src={src} {...props} />
}

function ImageResource({
  src,
  width,
  height,
  fill,
  blurDataURL,
  className,
  imageClassName,
  style,
  onLoad,
  onError,
  ref,
  ...props
}: ImageProps) {
  const [state, setState] = useState<"loading" | "ready" | "error">("loading")
  const data =
    typeof src === "object" ? ("default" in src ? src.default : src) : null
  const w = width ?? data?.width
  const h = height ?? data?.height
  const blur = blurDataURL ?? data?.blurDataURL
  return (
    <span
      data-slot="image"
      data-state={state}
      className={cn(
        "not-prose group/image relative block overflow-hidden bg-foreground/4",
        fill
          ? "absolute inset-0"
          : "w-(--image-width) max-w-full aspect-(--image-aspect)",
        className,
      )}
      style={
        {
          "--image-width": `${w}px`,
          "--image-aspect": `${w} / ${h}`,
          ...style,
        } as CSSProperties
      }
    >
      {blur && (
        <span
          aria-hidden="true"
          data-slot="image-placeholder"
          className="pointer-events-none absolute inset-0 overflow-hidden transition-opacity duration-300 motion-reduce:transition-none group-data-[state=ready]/image:opacity-0 group-data-[state=error]/image:opacity-0"
        >
          {/* Same fit and position as the final pixels, including transparent/contained media. */}
          {/* biome-ignore lint/performance/noImgElement: inline preview, no network or optimizer */}
          <img
            src={blur}
            alt=""
            className={cn("size-full object-cover", imageClassName)}
            style={{ filter: "blur(12px)" }}
          />
        </span>
      )}
      <NextImage
        {...props}
        src={src}
        width={width}
        height={height}
        fill={fill}
        ref={ref}
        data-slot="image-content"
        // Next's onLoad runs after decode(), including images cached before hydration.
        onLoad={(event) => {
          setState("ready")
          onLoad?.(event)
        }}
        onError={(event) => {
          setState("error")
          onError?.(event)
        }}
        className={cn(
          "relative block size-full object-cover transition-[opacity,filter] duration-300 ease-out motion-reduce:transition-none",
          "[@media(scripting:enabled)]:group-data-[state=loading]/image:opacity-0 motion-safe:[@media(scripting:enabled)]:group-data-[state=loading]/image:blur-sm",
          imageClassName,
        )}
      />
    </span>
  )
}

"use client"
import { type RefObject, useEffect, useState } from "react"

/** Shared intent for GIF and video covers. Explicit pause survives automatic triggers. */
export function useMediaIntent(
  frame: RefObject<HTMLElement | null>,
  interactionRef?: RefObject<HTMLElement | null>,
) {
  const [intent, setIntent] = useState(false)
  const [visible, setVisible] = useState(false)
  const [pageVisible, setPageVisible] = useState(true)
  const [touch, setTouch] = useState(false)
  const [reduced, setReduced] = useState(true)
  const [manual, setManual] = useState<boolean | null>(null)
  useEffect(() => {
    const root = frame.current
    if (!root) return
    const target = interactionRef?.current ?? root
    const hover = matchMedia("(hover: none)")
    const motion = matchMedia("(prefers-reduced-motion: reduce)")
    const preferences = () => {
      setTouch(hover.matches)
      setReduced(motion.matches)
    }
    const visibility = () =>
      setPageVisible(document.visibilityState === "visible")
    preferences()
    visibility()
    hover.addEventListener("change", preferences)
    motion.addEventListener("change", preferences)
    document.addEventListener("visibilitychange", visibility)
    let pointer = false,
      focus = false
    const update = () => setIntent(pointer || focus)
    const enter = () => {
      pointer = true
      update()
    }
    const leave = () => {
      pointer = false
      update()
    }
    const focusIn = () => {
      focus = true
      update()
    }
    const focusOut = (event: FocusEvent) => {
      focus =
        event.relatedTarget instanceof Node &&
        target.contains(event.relatedTarget)
      update()
    }
    target.addEventListener("pointerenter", enter)
    target.addEventListener("pointerleave", leave)
    target.addEventListener("focusin", focusIn)
    target.addEventListener("focusout", focusOut)
    const observer = new IntersectionObserver(
      ([entry]) =>
        setVisible(entry.isIntersecting && entry.intersectionRatio >= 0.5),
      { threshold: [0, 0.5] },
    )
    observer.observe(root)
    return () => {
      observer.disconnect()
      hover.removeEventListener("change", preferences)
      motion.removeEventListener("change", preferences)
      document.removeEventListener("visibilitychange", visibility)
      target.removeEventListener("pointerenter", enter)
      target.removeEventListener("pointerleave", leave)
      target.removeEventListener("focusin", focusIn)
      target.removeEventListener("focusout", focusOut)
    }
  }, [frame, interactionRef])
  return {
    manual,
    setManual,
    active: (playOn: "intent" | "visible" = "intent") =>
      visible &&
      pageVisible &&
      (manual ?? (!reduced && (playOn === "visible" || touch || intent))),
  }
}

"use client"
import { type RefObject, useRef } from "react"
import { cn } from "@/lib/utils"
import { Image } from "./image"
import { useMediaIntent } from "./image-intent"

export type AnimatedImageProps = {
  src: string
  poster: string
  width: number
  height: number
  alt: string
  blurDataURL?: string
  className?: string
  imageClassName?: string
  sizes?: string
  playOn?: "intent" | "visible"
  interactionRef?: RefObject<HTMLElement | null>
}

/** Native animated image, loaded only while requested. Stopping returns to its poster.
 * This does not promise frame-accurate pause/seek; use Video for those controls. */
export function AnimatedImage(props: AnimatedImageProps) {
  return <AnimationSource key={props.src} {...props} />
}
function AnimationSource({
  src,
  poster,
  width,
  height,
  alt,
  blurDataURL,
  className,
  imageClassName,
  sizes = "100vw",
  playOn,
  interactionRef,
}: AnimatedImageProps) {
  const frame = useRef<HTMLDivElement>(null)
  const intent = useMediaIntent(frame, interactionRef)
  const active = intent.active(playOn)
  return (
    <div
      ref={frame}
      data-slot="image-animation"
      data-playing={active}
      className={cn("not-prose relative max-w-full overflow-hidden", className)}
      style={{ aspectRatio: `${width} / ${height}` }}
    >
      <Image
        src={poster}
        alt={alt}
        fill
        sizes={sizes}
        blurDataURL={blurDataURL}
        imageClassName={imageClassName}
      />
      {active && (
        <Image
          src={src}
          alt=""
          aria-hidden
          fill
          unoptimized
          imageClassName={imageClassName}
        />
      )}
      <button
        type="button"
        aria-label={`${active ? "Pause" : "Play"} ${alt}`}
        aria-pressed={active}
        onClick={(e) => {
          e.preventDefault()
          e.stopPropagation()
          intent.setManual(!active)
        }}
        className="absolute right-2 bottom-2 rounded-full bg-black/60 px-3 py-2 text-xs text-white focus-visible:outline-2 focus-visible:outline-offset-2"
      >
        {active ? "pause" : "play"}
      </button>
    </div>
  )
}
